scwin.btn_setDisabled_onclick = function(e) {
    debugger;
    grd_main.setDisabled("column", "col4", true);
    grd_main.setDisabled("cell", "1", "col4", false);
};

scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_setDisabled').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_main_scrollY_div').scrollTop = 200");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_main_scrollY_div').scrollTop = 400");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_main_scrollY_div').scrollTop = 0");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById('grd_main_cell_1_3').childNodes[0]).hasClass('w2grid_input_disabled') == false", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
